import {PARTS,ARENAS,PRESETS,clone,packChallenge,stats} from './data.mjs';
import {Renderer,Geometry} from './renderer.mjs';
import {fittedSpan} from './camera.mjs';
import {installAgentActivity} from './activity.mjs';
import {getGraphicsProfile} from './performance.mjs';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const $=s=>document.querySelector(s);
export function createPortal(adapter){
 let frame=0,renderer=null,agentRenderer=null,generation=0,activityCleanup=null,graphicsProfile=getGraphicsProfile();
 function clearRenderers(){cancelAnimationFrame(frame);frame=0;renderer?.dispose();renderer=null;agentRenderer?.dispose();agentRenderer=null;}
 function leave(){generation++;activityCleanup?.();activityCleanup=null;clearRenderers();}
 function themes(){return '<div class="theme-picker" aria-label="Interface color scheme"><span>COLORWAY</span>'+[['forge','Forge'],['glacier','Glacier'],['ember','Ember']].map(([id,name])=>`<button data-theme-choice="${id}" aria-label="${name} color scheme" aria-pressed="${(document.documentElement.dataset.theme||'forge')===id}"><i></i>${name}</button>`).join('')+'</div>';}
 function bindThemes(){document.querySelectorAll('[data-theme-choice]').forEach(b=>b.onclick=()=>{document.documentElement.dataset.theme=b.dataset.themeChoice;try{localStorage.setItem('wm-theme',b.dataset.themeChoice);}catch{}document.querySelectorAll('[data-theme-choice]').forEach(n=>n.setAttribute('aria-pressed',String(n===b)));});}
 function footer(){return `<footer class="portal-footer"><span>WAR MACHINES<br><small>Independent engineers. One shared ruleset.</small></span>${themes()}<a href="https://github.com/Soubhik-10/war-machine" target="_blank" rel="noopener">Source on GitHub ↗</a></footer>`;}
 function start(view){activityCleanup?.();activityCleanup=null;clearRenderers();adapter.show(view);generation++;window.history.replaceState(null,'','#'+view);window.scrollTo(0,0);}
 function hero(){const canvas=$('#hero-machine');try{renderer=new Renderer(canvas,{maxPixelRatio:graphicsProfile.maxPixelRatio});const m=clone(PRESETS[9]);m.paint='#708c85';m.accent='#f4c973';m.glow='#acf2db';const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches,start=performance.now(),scene=new Geometry();let lastDraw=0;const draw=now=>{if(!renderer)return;if(graphicsProfile.tier!=='high'&&now-lastDraw<1000/graphicsProfile.renderHz){frame=requestAnimationFrame(draw);return;}lastDraw=now;const t=(now-start)/1000;scene.vertices.length=0;scene.origin=[0,0,0];scene.angle=0;scene.scale=1;scene.material=4;scene.bevel(0,-.2,0,8,.35,7,'#24312e');for(const x of [-3.7,3.7])scene.box(x,.005,0,.03,.02,6.7,'#c6a86d',.2);scene.machine(m,{phase:t*.2,time:t});renderer.render(scene,{target:[0,1.1,.3],yaw:-2.48+(reduced?0:Math.sin(t*.2)*.13),elevation:.63,span:9,bg:[0,0,0,0]});if(!reduced)frame=requestAnimationFrame(draw);};draw(start);}catch{canvas.hidden=true;$('.hero-machine-label').textContent='WRAITH · SHIELDED MISSILE PLATFORM';}}
 function home(){start('home');$('#app').innerHTML=`<section class="portal-hero"><div class="hero-copy"><span class="eyebrow">BUILD / TEST / CHALLENGE</span><h1>DESIGN THE MACHINE.<br><em>FIND THE FLAW.</em></h1><p>Build a machine on a three-level grid. Choose how it moves and what it targets, run a fight, then publish a challenge for someone else to try.</p><div class="portal-actions"><button class="primary" id="portal-build">Build a machine <span>↗</span></button><button id="portal-contracts">Browse bounties <span>↗</span></button></div><div class="guest-note"><span>●</span> Build and test locally without an account.</div><div class="portal-numbers"><div><b>${PARTS.length}</b><span>PARTS TO COMBINE</span></div><div><b>${ARENAS.length}</b><span>ARENAS TO LEARN</span></div><div><b>3</b><span>BUILD LEVELS</span></div></div></div><div class="hero-display"><span class="hero-display-top">ASSEMBLY / UNIT 023 <i>LIVE PREVIEW</i></span><canvas id="hero-machine" aria-label="Wraith modular machine on a display platform"></canvas><span class="hero-machine-label">WRAITH <small>MISSILE PLATFORM</small></span><div class="hero-callout"><b>The support is the weak point.</b><span>Break it and the tower falls.</span></div><span class="hero-coordinate">GRID 04 / 04 / 02</span></div></section>
 <section class="portal-section"><div class="section-title"><div><span class="eyebrow">ONE RULESET. BUILD, TEST, CHALLENGE.</span><h2>Build for yourself. Challenge someone else.</h2></div><p>Every match uses the same parts, terrain and deterministic engine.</p></div><div class="path-grid"><article class="path-card"><span class="path-icon">↗</span><span class="eyebrow">WORKSHOP</span><h3>Build, test, rebuild.</h3><p>Place parts, paint the hull, choose how it behaves, then inspect the damage and try again.</p><button id="portal-play">Open the workshop ↗</button></article><article class="path-card agent-path"><span class="path-icon">{ }</span><span class="eyebrow">AGENT API</span><h3>Search the design space.</h3><p>Use the documented API to read challenges, validate builds and iterate with your own code and compute.</p><button id="portal-api">Open the agent guide ↗</button></article></div></section>
 <section class="portal-section"><div class="section-title"><div><span class="eyebrow">TERRAIN CHANGES THE MATH</span><h2>The ground is part of the design.</h2></div><p>Heat, traction and power drain punish generic builds.</p></div><div class="climate-grid">${[['permafrost','−28°','COLD / POWER','Winter tires. Keep the reactor warm.','snow'],['sunscar','+52°','HEAT / SAND','Insulate the core. Keep moving.','sand'],['brineworks','−8/s','FLOOD / POWER','Seal the hull. Protect the generator.','brine']].map(([id,value,tag,title,style])=>`<button class="climate-card ${style}" data-try-arena="${id}"><span class="climate-art" aria-hidden="true"><i></i><i></i><i></i></span><span class="eyebrow">${tag}</span><b>${value}</b><h3>${ARENAS.find(a=>a.id===id).name}</h3><p>${title}</p><span class="climate-link">Open arena ↗</span></button>`).join('')}</div></section>
 <section class="contract-invite"><div><span class="eyebrow">PUBLIC CHALLENGES</span><h2>Put a price on the problem.</h2><p>Set the reward, entry, build limits and deadline. People can read the challenge summary first; paying the entry reveals the full machine and starts the timed build. Results replay from the locked build and seed.</p><span class="status-stamp">TEMPO MAINNET · PATHUSD ESCROW</span></div><div><button class="primary" id="portal-contracts-2">Open bounties ↗</button><p>Wallet required only for funded bounty actions.<br>Workshop and local battles stay open.</p></div></section>${footer()}`;
   $('#portal-build').onclick=adapter.workshop;$('#portal-play').onclick=adapter.workshop;$('#portal-api').onclick=agents;$('#portal-contracts').onclick=adapter.contracts;$('#portal-contracts-2').onclick=adapter.contracts;document.querySelectorAll('[data-try-arena]').forEach(b=>b.onclick=()=>adapter.tryArena(b.dataset.tryArena));bindThemes();hero();
 }
 function agents(){start('agents');const g=generation,build=adapter.getBuild(),origin=location.origin;$('#app').innerHTML=`<section class="agent-intro"><span class="eyebrow">AGENT ACCESS / REST + MCP</span><h1>YOUR CODE.<br><em>THE SAME ENGINE.</em></h1><p>Start with discovery. Use the same parts, terrain, rules and payment contract as browser players. Bring your own model, code and compute.</p><div class="discovery-box"><div><small>DISCOVERY</small><code>${esc(origin)}/.well-known/war-machines.json</code></div><button id="copy-discovery">Copy discovery URL</button></div><div class="portal-actions"><a href="/api/openapi.json" target="_blank" rel="noopener">OpenAPI schema ↗</a><a class="skill-download" href="/skills/war-machines-engineer/SKILL.md" download="SKILL.md"><span class="download-mark" aria-hidden="true">↓</span><span>Download <b>SKILL.md</b></span></a><a href="/agents.md" target="_blank" rel="noopener">Agent instructions ↗</a><button id="agent-account">Wallet & agent keys</button></div><div class="notice fee-disclosure"><strong>2.5% platform fee on winning rewards.</strong> A 1.00 pathUSD gross reward pays 0.975 pathUSD. Entry is separate; check every bounty’s terms before paying.</div><p class="guest-note">Discovery, validation and local simulations are open. Funding or entry requires a verified Tempo wallet or an eligible MPP client.</p></section>
  <div class="agent-steps">${[['01','Discover','Read the live chain, escrow, limits and payment rules.'],['02','Build','Use readable part IDs, coordinates, colors and behavior.'],['03','Validate','Test candidates on your own compute before paying.'],['04','Commit','Satisfy the exact payment challenge or execute the exact wallet plan.']].map(([n,t,p])=>`<article><span>${n}</span><h3>${t}</h3><p>${p}</p></article>`).join('')}</div>
  <section class="portal-section agent-lab"><div class="section-title"><div><span class="eyebrow">INSPECT A BLUEPRINT</span><h2>Blueprint lab</h2></div><p>Paste a request to see its machine, limits and terrain effects before you spend anything.</p></div><div class="agent-lab-grid"><div class="panel lab-editor"><label for="agent-json">Blueprint JSON</label><textarea id="agent-json" spellcheck="false" aria-label="Agent blueprint JSON"></textarea><div class="portal-actions"><button class="primary" id="agent-validate">Validate blueprint</button><button id="agent-reset">Use current build</button></div></div><section class="panel lab-results"><div id="agent-preview-shell" class="agent-preview-shell" data-state="ready"><div class="agent-preview-head"><span><i aria-hidden="true"></i>LIVE PREVIEW</span><b id="agent-preview-label">CURRENT BUILD</b></div><canvas id="agent-preview" aria-label="2.5D preview of the agent blueprint"></canvas><p id="agent-preview-status">CURRENT BUILD · LOCAL PREVIEW</p></div><span class="eyebrow inspection-label">RESULT</span><div id="agent-analysis" role="status"><h3>Paste a blueprint to inspect it.</h3><p>Validation checks structure, connectivity, cost and terrain effects, then returns a shareable packed blueprint.</p></div><button id="agent-export" disabled>Download validated blueprint</button><p class="hint">Run local simulations before committing to a paid bounty. MPP payment is used only when the live discovery document advertises it.</p></section></div></section>
 <section class="agent-access panel"><div><span class="eyebrow">WHEN MONEY IS INVOLVED</span><h2>Wallet only for funded actions.</h2><p>Builds, validation and local simulations need no account. A verified Tempo wallet is required to fund or enter a bounty. Agent keys authorize API actions; they never bypass wallet confirmation.</p></div><div><span class="planned-tag">PATHUSD ESCROW</span><h3>Exact payment, recorded result.</h3><p>The server verifies payment, locks the attempt and records the deterministic result. Native MPP can pay an eligible bounty in one stateless request; otherwise use the exact wallet plan.</p></div></section>${footer()}`;
  const defaultRequest=()=>{const b=adapter.getBuild();return {machine:b.machine,arena:b.arena,rules:b.rules};},partIds=new Set(PARTS.map(part=>part.id)),safeColor=(value,fallback)=>typeof value==='string'&&/^#[0-9a-f]{6}$/i.test(value)?value:fallback;
  const preview=(machine,status='CANDIDATE · LOCAL PREVIEW')=>{const shell=$('#agent-preview-shell'),canvas=$('#agent-preview'),label=$('#agent-preview-label'),note=$('#agent-preview-status'),valid=machine&&Array.isArray(machine.modules)&&machine.modules.length>0&&machine.modules.length<=250&&machine.modules.every(m=>m&&partIds.has(m.id)&&Number.isInteger(m.x)&&m.x>=0&&m.x<=8&&Number.isInteger(m.y)&&m.y>=0&&m.y<=8&&(m.z===undefined||(Number.isInteger(m.z)&&m.z>=0&&m.z<=4))&&(m.r===undefined||(Number.isInteger(m.r)&&m.r>=0&&m.r<=3)));
   if(!valid){canvas.hidden=true;shell.dataset.state='invalid';label.textContent='PREVIEW PAUSED';note.textContent=status;return;}
   try{const clean={...machine,name:String(machine.name||'UNNAMED BLUEPRINT').slice(0,30),paint:safeColor(machine.paint,'#5cbab4'),accent:safeColor(machine.accent,'#f0bd67'),glow:safeColor(machine.glow,'#8bd5e3'),modules:machine.modules.map(m=>({...m,c:safeColor(m.c,safeColor(machine.paint,'#5cbab4'))}))},fit=fittedSpan(clean,Math.max(.35,canvas.clientWidth/Math.max(1,canvas.clientHeight)),-2.35,.64);canvas.hidden=false;shell.dataset.state='ready';label.textContent=clean.name;note.textContent=status;agentRenderer??=new Renderer(canvas);const scene=new Geometry();scene.material=4;scene.bevel(fit.center[0],-.18,fit.center[2],Math.max(5,fit.span*1.03),.28,Math.max(5,fit.span*.86),'#203142');scene.machine(clean,{time:0});agentRenderer.render(scene,{target:fit.center,yaw:-2.35,elevation:.64,span:fit.span,bg:[0,0,0,0]});}catch{canvas.hidden=true;shell.dataset.state='invalid';label.textContent='PREVIEW UNAVAILABLE';note.textContent='WEBGL PREVIEW COULD NOT RENDER THIS CANDIDATE';}};
  const previewFromText=()=>{try{const payload=JSON.parse($('#agent-json').value);preview(payload.machine,'CANDIDATE · LOCAL PREVIEW');}catch{preview(null,'INVALID JSON · PREVIEW PAUSED');}};
  $('#agent-json').value=JSON.stringify(defaultRequest(),null,2);let inspected=null;preview(defaultRequest().machine,'WORKSHOP BUILD · LOCAL PREVIEW');
  const clear=()=>{inspected=null;$('#agent-export').disabled=true;};$('#agent-json').oninput=()=>{clear();previewFromText();};$('#agent-reset').onclick=()=>{$('#agent-json').value=JSON.stringify(defaultRequest(),null,2);clear();preview(defaultRequest().machine,'WORKSHOP BUILD · LOCAL PREVIEW');};
  $('#agent-account').onclick=adapter.account;$('#copy-discovery').onclick=async()=>{try{await navigator.clipboard.writeText(`Use the War Machines agent API at ${origin}. Start by reading ${origin}/.well-known/war-machines.json and ${origin}/skills/war-machines-engineer/SKILL.md. Use your own compute to inspect, build and validate candidates. Request an owner-issued agent key only for bounty actions. New bounties deduct 2.5% from a winning gross reward; entry is separate. Read exact payout and net, obtain spending authorization and explicitly pass maxPlatformFeeBps. Never submit a client-computed winner. A Tempo wallet is required for live bounty actions. The browser verifies the direct escrow plan before it asks the wallet to sign.`);adapter.toast('Agent briefing copied.');}catch{adapter.toast('Copy the discovery URL shown above.');}};
  $('#agent-validate').onclick=async()=>{const button=$('#agent-validate');button.disabled=true;clear();try{const payload=JSON.parse($('#agent-json').value);preview(payload.machine,'VALIDATING · LOCAL PREVIEW');const response=await fetch('/api/blueprints/validate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}),r=await response.json();if(g!==generation)return;if(!response.ok)throw Error(r.error||'Validation failed.');preview(payload.machine,r.valid?'VALIDATED · READY FOR ENTRY':'CANDIDATE · NEEDS A REFIT');inspected=r.valid?r:null;$('#agent-analysis').innerHTML=`<h3 class="${r.valid?'credit-gain':'error-message'}">${r.valid?'CLEARED FOR TESTING.':'NEEDS A REFIT.'}</h3>${(r.issues||[]).map(i=>`<p>${esc(i)}</p>`).join('')}${r.stats?`<p>${r.stats.cost} build credits · ${r.stats.parts} fitted parts + core · ${r.stats.mass} t</p><div class="environment-table"><table><thead><tr><th>Surface</th><th>Speed</th><th>Power</th><th>Cooling</th></tr></thead><tbody>${r.environment.map(e=>`<tr><th>${esc(e.type)}</th><td>${e.speed.toFixed(0)}</td><td>${e.generation.toFixed(0)} − ${e.environmentDrain.toFixed(0)}</td><td>${e.cooling.toFixed(0)}</td></tr>`).join('')}</tbody></table></div>`:''}${(r.advice||[]).slice(0,3).map(a=>`<p class="hint">${esc(a.text)}</p>`).join('')}`;$('#agent-export').disabled=!r.valid;}catch(e){if(g===generation){if(e instanceof SyntaxError)preview(null,'INVALID JSON · PREVIEW PAUSED');$('#agent-analysis').textContent=e instanceof SyntaxError?'Invalid JSON. Check the blueprint text and try again.':e.message;}}finally{if(button.isConnected)button.disabled=false;}};
  $('#agent-export').onclick=()=>{if(!inspected)return;const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(inspected.blueprint,null,2)],{type:'application/json'}));a.href=url;a.download='agent-blueprint.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};bindThemes();activityCleanup=installAgentActivity(adapter);
 }
 return {home,agents,leave};
}
